SELECT store_id, CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END AS revenue_tier, COUNT(DISTINCT product_id) AS distinct_product_ids, SUM(revenue) AS total_revenue, STDDEV_SAMP(revenue) AS revenue_stddev, COUNT(*) AS event_count, GROUPING_ID() AS gid FROM store_sales GROUP BY GROUPING SETS ((store_id, CASE WHEN revenue >= 3400 THEN 'PREMIUM' ELSE 'STANDARD' END), (store_id), ()) ORDER BY event_count DESC;
